#pragma once#include "BaseReader.h"class KPID : public KBaseReader{public:  KPID();  virtual std::string GetType() const  {    return "PID";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_settings;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_settings;};//////////////////////////////////////////////////////////////////////////class KPIDFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KPID();    return ptr;  }};